package android.media; import java.nio.ByteBuffer; import java.util.ArrayDeque; import android.view.Surface; public class MediaCodec { public static final int INFO_OUTPUT_FORMAT_CHANGED=-2; public static boolean busy; public static String lastMime; public static int dropped,configureCalls,releases; public static boolean rejectVendor,rejectGeneric; public static long lastReleaseNs; public static class BufferInfo { public long presentationTimeUs; } private Surface surface; private int serial; private final java.util.HashMap<Integer,Long> pts=new java.util.HashMap<>(); private final ArrayDeque<Integer> output=new ArrayDeque<>(); public static MediaCodec createDecoderByType(String type){lastMime=type;return new MediaCodec();} public void configure(MediaFormat f,Surface s,Object c,int flags){configureCalls++; if((rejectVendor && f.values.containsKey("vendor.rtc-ext-dec-low-latency.enable")) || (rejectGeneric && f.values.containsKey(MediaFormat.KEY_LOW_LATENCY)))throw new IllegalArgumentException("Rejected low latency option");surface=s;} public String getName(){return "c2.exynos.mock.avc.decoder";} public void start(){} public int dequeueInputBuffer(long timeout){return busy?-1:0;} public ByteBuffer getInputBuffer(int index){return ByteBuffer.allocate(2*1024*1024);} public void queueInputBuffer(int index,int offset,int length,long timestamp,int flags){output.add(++serial);pts.put(serial,timestamp);} public int dequeueOutputBuffer(BufferInfo info,long timeout){Integer index=output.poll();if(index!=null)info.presentationTimeUs=pts.remove(index);return index==null?-1:index;} public void releaseOutputBuffer(int index,boolean render){if(render)surface.texture.render();else dropped++;} public void releaseOutputBuffer(int index,long time){lastReleaseNs=time;releaseOutputBuffer(index,true);} public void flush(){output.clear();} public void stop(){} public void release(){releases++;} }
